  def fetchContainer(): scp_candidate.Mining_Threat_Retreat_Supervision.Priority_Arbitration_supervisor_process_priority_arbitration_PostState_Container_PS = {
    if (runtimeMonitorStream.contains(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.id)) {
      val (_, postContainer_) = runtimeMonitorStream.get(Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.id).get
      return postContainer_.asInstanceOf[scp_candidate.Mining_Threat_Retreat_Supervision.Priority_Arbitration_supervisor_process_priority_arbitration_PostState_Container_PS]
    }
    else {
      assert(F, s"No post state recorded for ${Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.name}")
      halt(s"No post state recorded for ${Arch.Mining_Threat_Retreat_Supervision_Root_Instance_supervisor_process_priority_arbitration.name}")
