  }

  def check_concrete_outputs(api_selected_action: Mining_Threat_Retreat_Supervision.ActionValue,
                             api_selected_cause: Mining_Threat_Retreat_Supervision.SelectedCauseValue): Unit = {
    var failureReasons: ISZ[ST] = ISZ()

    val actual_selected_action = get_api_selected_action()
    if (api_selected_action != actual_selected_action) {
      failureReasons = failureReasons :+ st"'selected_action' did not match expected.  Expected: $api_selected_action, Actual: $actual_selected_action"
    }
    val actual_selected_cause = get_api_selected_cause()
    if (api_selected_cause != actual_selected_cause) {
      failureReasons = failureReasons :+ st"'selected_cause' did not match expected.  Expected: $api_selected_cause, Actual: $actual_selected_cause"
    }

    assert(failureReasons.isEmpty, st"${(failureReasons, "\n")}".render)
  }

  def get_api_selected_action(): Mining_Threat_Retreat_Supervision.ActionValue = {
    return fetchContainer().api_selected_action
